        out = [[0]*out_w for _ in range(out_h)]
        for i in range(out_h):
            for j in range(out_w):
                left_val = grid[i][j]
                right_val = grid[i][j + sep_col_idx + 1]
                if left_val != 0 and right_val != 0:
                    out[i][j] = (left_val + right_val) - sep_col_val
        return out

    return grid

